api.script:

import dtk;
import log;
var paraMap = {};
paraMap.url = "/api/goods/singlePage/list-height-commission";
paraMap.pageId = body.pageId ? body.pageId : "1";
paraMap.pageSize = body.pageSize ? body.pageSize : "20";

var raw = dtk.execute(paraMap);
var rawData = (raw && raw.data) ? raw.data : {};

var result = {};
result.list = (rawData && rawData.list) ? rawData.list : [];
result.total = (rawData && rawData.totalNum != null) ? rawData.totalNum : 0;
return result;


